class Component extends DCLogic {
  constructor(props) { super(props); this.state = { hasKey: false, show: false, m: '', mt: 'api', lf: 'all', tName: '', tPhone: '', tn: false, tp: false, res: '', oCode: '', oc: false, lang: 'ru', accepted: false, o: {}, sent: false,
    log: [['Иван Новиков', 'API / curl · 06.11, 18:04', 'Новая', 'real'], ['Мария Назарова', 'API / curl · 05.11, 20:28', 'Новая', 'real'], ['Клиент по ссылке 2', 'API / curl · 02.11, 20:28', 'Квалификация', 'real'], ['Клиент по ссылке 3', 'API / curl · 31.10, 20:28', 'Квалификация', 'real'], ['Тестовый клиент TEST', 'API / curl · 06.11, 11:02', 'Новая', 'test']] }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state, EP = 'https://housebook.global/api/partner/intake';
    const KEY = 'hb_live_4f9a2c71d08e5b36a9c2e';
    const sec = (k) => ({ ['o_' + k]: !!S.o[k], ['t_' + k]: () => this.setState({ o: Object.assign({}, S.o, { [k]: !S.o[k] }) }) });
    const CODE = { api: 'curl -X POST "' + EP + '" \\\n  -H "x-api-key: YOUR_API_KEY" \\\n  -H "content-type: application/json" \\\n  -d \'{"name": "Ivan Petrov", "phone": "+66812345678", "email": "ivan@example.com", "externalId": "crm-12345"}\'',
      form: '<form method="POST" action="' + EP + '">\n  <input type="hidden" name="x-api-key" value="YOUR_API_KEY" />\n  <input name="name" placeholder="Name" required />\n  <input name="phone" placeholder="Phone" required />\n  <button type="submit">Send</button>\n</form>' };
    const TXT = { api: 'Отправьте запрос со своего сервера. Имя и телефон обязательны, остальное по желанию.', hook: 'В своей системе учёта клиентов настройте отправку данных на адрес выше (это называется вебхук). Передайте поля: name (имя), phone (телефон), email, projectName, budget, comment, externalId. Имя и телефон обязательны.', nocode: 'В Make, Zapier, n8n, Tilda или Webflow добавьте шаг «отправить запрос» (HTTP). Метод POST, адрес выше, заголовок x-api-key с Вашим ключом, в теле name, phone и остальные поля. Запустите сценарий и проверьте журнал ниже.', form: 'Готовая форма для сайта.' };
    const MT = [['api', 'API'], ['hook', 'Из системы учёта клиентов'], ['nocode', 'Без программирования'], ['form', 'Форма на сайте']];
    const mTabs = MT.map(([k, t]) => ({ t, on: S.mt === k, pick: () => this.setState({ mt: k }) }));
    const FL = [['all', 'Все'], ['real', 'Реальные'], ['test', 'Тестовые']];
    const fl = FL.map(([k, t]) => ({ t, on: S.lf === k, pick: () => this.setState({ lf: k }) }));
    const rows = S.log.filter((r) => S.lf === 'all' || r[3] === S.lf).map((r) => ({ name: r[0], sub: r[1], st: r[2] }));
    const ask = (name) => (e) => this.openM(name, e);
    return Object.assign(this.baseVals(), sec('st'), sec('lm'), sec('of'), { noKey: !S.hasKey, hasKey: S.hasKey, mTabs, fl, rows, rowsEmpty: rows.length === 0, total: 71 + S.log.length - 5,
      keyShown: S.show ? KEY : 'hb_live_••••••••••••••••9c2e', showLabel: S.show ? 'Скрыть' : 'Показать', toggleShow: () => this.setState({ show: !S.show }),
      copyEp: (e) => this.say('Адрес скопирован', e), copyKey: (e) => this.say('Ключ скопирован', e), copyCode: (e) => this.say('Скопировано', e),
      getKey: (e) => { this.setState({ hasKey: true, show: true }); this.say('Ключ выпущен. Сохраните его', e); },
      askNew: ask('new'), askRevoke: ask('rev'), askOffer: ask('off'),
      doNew: (e) => { this.setState({ m: '', show: true }); this.say('Новый ключ выпущен, старый отключён', e); },
      doRevoke: (e) => { this.setState({ m: '', hasKey: false, show: false }); this.say('Ключ отозван', e); },
      m_new: S.m === 'new', m_rev: S.m === 'rev', m_off: S.m === 'off',
      mText: TXT[S.mt], mHasCode: S.mt === 'api' || S.mt === 'form', mCode: CODE[S.mt === 'form' ? 'form' : 'api'], mWarn: S.mt === 'form',
      tName: S.tName, tPhone: S.tPhone, setTn: (e) => this.setState({ tName: e.target.value, tn: false }), setTp: (e) => this.setState({ tPhone: e.target.value, tp: false }),
      c_tn: S.tn ? 'is-err' : '', m_tn: S.tn ? 'Введите имя' : '', c_tp: S.tp ? 'is-err' : '', m_tp: S.tp ? 'Введите телефон' : '', hasRes: !!S.res, res: S.res,
      sendTest: (e) => { const bad = { tn: !S.tName.trim(), tp: S.tPhone.replace(/\D/g, '').length < 7 };
        if (!S.hasKey) { this.setState({ res: '' }); this.say('Сначала получите ключ', e); return; }
        if (bad.tn || bad.tp) { this.setState(bad); return; }
        this.setState({ res: 'Связь есть. Тестовый клиент принят и записан в журнал с пометкой TEST.', log: [[S.tName.trim() + ' TEST', 'API / curl · сейчас', 'Новая', 'test']].concat(S.log), tName: '', tPhone: '' }); },
      accepted: S.accepted, notAccepted: !S.accepted,
      langs: [['ru', 'Русский'], ['en', 'English']].map(([k, t]) => ({ t, on: S.lang === k, pick: () => this.setState({ lang: k }) })),
      sendCode: (e) => this.say('Код отправлен на почту', e), oCode: S.oCode, setOc: (e) => this.setState({ oCode: e.target.value.replace(/\D/g, '').slice(0, 6), oc: false }), c_oc: S.oc ? 'is-err' : '', m_oc: S.oc ? 'Код не подошёл' : '',
      doOffer: (e) => { if (S.oCode !== '123456') { this.setState({ oc: true }); return; } this.setState({ m: '', accepted: true, oCode: '' }); this.say('Дополнение принято', e); } });
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice()) this.state.log = []; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); const nov = HB.isNovice(); v.total = (nov ? 0 : 66) + S.log.length; v.monthN = (nov ? 0 : 9) + S.log.length;
    v.emptyT = S.lf === 'all' ? 'Передач через API пока не было. Получите ключ и отправьте тест.' : 'В этом фильтре пока пусто.'; return v; }
}; })(Component);
